package android.app; import java.util.*;
public class AlarmManager { public static final int RTC_WAKEUP=0; public boolean exactAllowed=true; public boolean throwSecurity; public final List<Alarm> alarms=new ArrayList<>(); public final List<PendingIntent> cancelled=new ArrayList<>(); public boolean canScheduleExactAlarms(){return exactAllowed;} public void setExactAndAllowWhileIdle(int type,long at,PendingIntent op){if(throwSecurity)throw new SecurityException("denied by test");replace(new Alarm(true,at,op));} public void setAndAllowWhileIdle(int type,long at,PendingIntent op){if(throwSecurity)throw new SecurityException("denied by test");replace(new Alarm(false,at,op));} public void cancel(PendingIntent op){cancelled.add(op);alarms.removeIf(a->a.operation.identity().equals(op.identity()));} private void replace(Alarm n){alarms.removeIf(a->a.operation.identity().equals(n.operation.identity()));alarms.add(n);} public static final class Alarm { public final boolean exact; public final long at; public final PendingIntent operation; Alarm(boolean e,long a,PendingIntent o){exact=e;at=a;operation=o;} } }
